-- Phase 4 schema was applied to production through Supabase migration tooling.
-- This file versions the additive schema in GitHub for reproducibility.
create table if not exists jarvis_heartbeat_runs(id text primary key,trigger_type text not null,status text not null,started_at timestamptz not null default now(),completed_at timestamptz,previous_success_id text,source_summary jsonb not null default '{}'::jsonb,delta_summary jsonb not null default '{}'::jsonb,reasoning_summary jsonb not null default '{}'::jsonb,error_summary jsonb not null default '{}'::jsonb,code_version text,data jsonb not null default '{}'::jsonb);
create table if not exists jarvis_black_box_events(id text primary key,heartbeat_id text,event_type text not null,source_type text,source_record_id text,entity_ids jsonb not null default '[]'::jsonb,situation_ids jsonb not null default '[]'::jsonb,evidence_ids jsonb not null default '[]'::jsonb,reasoning_id text,decision_id text,authority_mode text,before_hash text,after_hash text,code_version text,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists jarvis_source_cursors(source_id text primary key,cursor_value text,last_attempt_at timestamptz,last_success_at timestamptz,freshness_status text,connection_status text,consecutive_failures integer not null default 0,last_error text,metadata jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists jarvis_interventions(id text primary key,decision_id text,situation_id text,status text not null default 'NEW',priority integer not null default 0,title text,summary text,reason_codes jsonb not null default '[]'::jsonb,options jsonb not null default '[]'::jsonb,prepared jsonb not null default '{}'::jsonb,first_seen_at timestamptz not null default now(),last_changed_at timestamptz not null default now(),seen_at timestamptz,resolved_at timestamptz,superseded_by text,data jsonb not null default '{}'::jsonb);
create table if not exists jarvis_delegations(id text primary key,action_type text not null,scope text not null,status text not null default 'PROPOSED',conditions jsonb not null default '{}'::jsonb,exceptions jsonb not null default '[]'::jsonb,min_confidence real not null default .95,granted_by text,granted_at timestamptz,revoked_at timestamptz,observations integer not null default 0,successful_outcomes integer not null default 0,data jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table jarvis_heartbeat_runs enable row level security;alter table jarvis_black_box_events enable row level security;alter table jarvis_source_cursors enable row level security;alter table jarvis_interventions enable row level security;alter table jarvis_delegations enable row level security;
